// chapter001.js —— 1-1 ~ 2-1 完整 807 句台词
export var chapter001 = [[0, "", "『先生』", null, "画面_黒", "bgm01.opus", null], [1, "将臣", "「……」", null, "画面_黒", "bgm01.opus", null], [2, "", "『先生』", null, "画面_黒", "bgm01.opus", null], [3, "将臣", "「……呃？」", null, "画面_黒", "bgm01.opus", null], [4, "司机", "「先生您醒醒」", "uts001_001.ogg", "空_青空", "bgm01.opus", null], [5, "将臣", "「啊，不好意思。怎么了？」", null, "空_青空", "bgm01.opus", null], [6, "", "我猛地坐了起来，连忙应了一声。", null, "空_青空", "bgm01.opus", null], [7, "司机", "「马上就快到了，请问咱们在哪停车？」", "uts001_002.ogg", "空_青空", "bgm01.opus", null], [8, "将臣", "「啊？哦，已经快到了啊」", null, "空_青空", "bgm01.opus", null], [9, "", "在车站附近找到出租车后，我竟不知不觉一路睡到现在。", null, "空_青空", "bgm01.opus", null], [10, "", "而且上车时，我似乎只对司机说了个大概的位置。", null, "空_青空", "bgm01.opus", null], [11, "将臣", "「能麻烦您送我到志那都庄吗」", null, "空_青空", "bgm01.opus", null], [12, "司机", "「啊……抱歉。这一带我不是很熟来着」", "uts001_003.ogg", "空_青空", "bgm01.opus", null], [13, "司机", "「所以……可不可以不进里面？」", "uts001_004.ogg", "空_青空", "bgm01.opus", null], [14, "将臣", "「（这什么服务态度啊……）」", null, "空_青空", "bgm01.opus", null], [15, "", "看到我一脸不满的表情，司机摆出了一副营业式的微笑。", null, "空_青空", "bgm01.opus", null], [16, "司机", "「真的很抱歉」", "uts001_005.ogg", "空_青空", "bgm01.opus", null], [17, "将臣", "「……好吧。那就在这儿停吧」", null, "空_青空", "bgm01.opus", null], [18, "司机", "「感谢您的理解」", "uts001_006.ogg", "空_青空", "bgm01.opus", null], [19, "", "出租车停在路边，我结完账后准备下车。", null, "空_青空", "bgm01.opus", null], [20, "司机", "「竟然专门跑到这犬魂作祟的地方来看庆典，最近不怕死的人也是越来越多了……」", "uts001_007.ogg", "空_青空", "bgm01.opus", null], [21, "将臣", "「……」", null, "空_青空", "bgm01.opus", null], [22, "", "正要下车时听见了这么一句话。", null, "空_青空", "bgm01.opus", null], [23, "", "我懒得搭理他，直接下了车。", null, "空_青空", "bgm01.opus", null], [24, "将臣", "「这还真有点远啊……也罢，反正好久没来了，边走边逛吧」", null, "街_雰囲気モブa", "bgm01.opus", null], [25, "", "我长吁一口气，双手叉腰，使劲伸展了一下后背。", null, "街_雰囲気モブa", "bgm01.opus", null], [26, "", "腰部发出咯吱咯吱的响声。看来是坐太久了。", null, "街_雰囲気モブa", "bgm01.opus", null], [27, "将臣", "「嗯———！累死了————！」", null, "街_雰囲気モブa", "bgm01.opus", null], [28, "", "出家门后，算上换乘我一共坐了２个小时的电车。", null, "街_雰囲気モブa", "bgm01.opus", null], [29, "", "然后又在出租车上颠簸了３０分钟。", null, "街_雰囲気モブa", "bgm01.opus", null], [30, "", "一路上坡道连连，四周尽是些绿得流油的树木，毫无看头。过了坡道，我才终于抵达穗织镇。", null, "街_雰囲気モブa", "bgm01.opus", null], [31, "将臣", "「这地方还是那么不方便啊」", null, "街_雰囲気モブa", "bgm01.opus", null], [32, "", "这里不仅没有通电车，唯一的公共交通工具——\\n公交车——也是一个小时才有一班。", null, "街_雰囲気モブa", "bgm01.opus", null], [33, "", "要是坐公交来，得花上一个多小时，而且公交的运营时间不包含清晨和晚上。", null, "街_雰囲気モブa", "bgm01.opus", null], [34, "", "除了打的和公交之外，就只能自己开车来了。", null, "街_雰囲気モブa", "bgm01.opus", null], [35, "", "毕竟这是偏僻的山区。在这里，只靠两条腿永远也别想走出大自然的怀抱。", null, "街_雰囲気モブa", "bgm01.opus", null], [36, "", "――不过，偏僻是偏僻，镇上倒还挺热闹的。", null, "街_雰囲気モブa", "bgm01.opus", null], [37, "", "原因之一便是在于这城镇风貌。", null, "街_雰囲気モブa", "bgm01.opus", null], [38, "", "小镇的街道精致而整洁，房舍之间洋溢着一股浓郁的“和风”，也难怪这里会被称为“小京都”了。", null, "街_雰囲気モブa", "bgm01.opus", null], [39, "", "跟路上那无聊透顶的山间风景比起来，这里的街道真的是处处透着美感。", null, "街_雰囲気モブa", "bgm01.opus", null], [40, "", "而且最重要的是，穗织镇以温泉闻名全国。闻名的理由则在于其功效。", null, "街_雰囲気モブa", "bgm01.opus", null], [41, "", "传言说，只要在穗织的温泉里泡上一会儿，腰也不酸了，腿也不痛了，肌肤还会变得光滑细腻。甚至还有人说，这里的温泉就是万能药。", null, "街_雰囲気モブa", "bgm01.opus", null], [42, "", "因此，从很久以前开始就有不少外地人会过来泡温泉疗养。", null, "街_雰囲気モブa", "bgm01.opus", null], [43, "", "近些年网络普及，口碑越传越好，还吸引了很多外国游客。现在我就能听到周边有不少人在用外语对话。", null, "街_雰囲気モブa", "bgm01.opus", null], [44, "将臣", "「……该赶路了」", null, "街_雰囲気モブa", "bgm01.opus", null], [45, "", "我可不是来旅游的，老在原地站着也不是个办法。", null, "街_雰囲気モブa", "bgm01.opus", null], [46, "芦花", "「……」", "rok001_001.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [47, "芦花", "「……呃……不好意思」", "rok001_002.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [48, "将臣", "「啊，怎么了？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [49, "芦花", "「你是阿将吗？我不确定我有没有认错……」", "rok001_003.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [50, "将臣", "「芦花姐？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [51, "芦花", "「果然是阿将啊！太好了，没有认错」", "rok001_004.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [52, "芦花", "「哎呀，真的是好久没见了」", "rok001_005.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "02"}], [53, "", "眼前这位笑容爽朗，正冲着我挥手的女性叫作马庭芦花。", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [54, "", "没记错的话……她应该是比我大两三岁。", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [55, "", "小时候我妈带着我一起回穗织镇时，芦花姐经常陪我玩。", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [56, "将臣", "「最近过得怎么样？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [57, "芦花", "「过得很好啦。你在那边过得怎么样？对了，我们是多少年没见了来着？」", "rok001_006.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [58, "将臣", "「我记得应该是……四年了吧？我过得也挺好的，身体可健康了」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [59, "芦花", "「是吗，都四年了……你长好高了呀，阿将」", "rok001_007.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "13"}], [60, "芦花", "「真是没想到，我现在都需要仰视你了。你小子竟然背着我偷偷长这么高，姐姐我好气啊」", "rok001_008.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "13"}], [61, "将臣", "「应该是去年吧，从那时起我就开始疯狂长个子了，有时候膝盖都会疼起来」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "13"}], [62, "芦花", "「也是……都四年了，大学都能毕业了。长这么高也是理所当然的……」", "rok001_009.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "28"}], [63, "将臣", "「芦花姐，你也有所成长吧……缩水应该也算成长？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "28"}], [64, "芦花", "「哟嗬。越夸你还越来劲了啊，来，头伸过来」", "rok001_010.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "13"}], [65, "", "芦花姐敲了敲我的脑袋。", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "13"}], [66, "芦花", "「你再长我就够不到你脑袋了……而且身体也长这么壮实，真是越来越像个大男人了」", "rok001_011.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [67, "将臣", "「托你的福啦」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [68, "芦花", "「话说，你是一个人来的？」", "rok001_012.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [69, "将臣", "「嗯。这次就我一个。而且是来给旅馆帮忙的」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [70, "都子", "「将臣，你去趟外公家吧」", "myk001_001.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [71, "将臣", "「啊？怎么这么突然？」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [72, "都子", "「外公开的旅馆，春夏季还有过年期间都很忙，你应该是知道的吧？」", "myk001_002.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [73, "将臣", "「嗯……是叫志那都庄来着？」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [74, "都子", "「外公说需要有人去帮忙」", "myk001_003.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [75, "将臣", "「那你去吧。特产就不用帮我带了」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [76, "都子", "「我怎么就生了你这样一个蠢儿子呢……」", "myk001_004.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [77, "将臣", "「凭什么让我去啊？以前每次不都是你去的吗」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [78, "都子", "「今年我没空嘛」", "myk001_005.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [79, "都子", "「我跟你爸已经订好机票了，要去欧洲玩一个多星期」", "myk001_006.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [80, "都子", "「而且，你已经好几年没见你外公了吧？刚好这次去见见他老人家」", "myk001_007.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [81, "将臣", "「……」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [82, "都子", "「你去的话还有工资可以拿。路费我给你报销」", "myk001_008.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [83, "都子", "「但你要是不去，我们旅行期间你伙食费自己想办法」", "myk001_009.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [84, "将臣", "「卑鄙！这也太卑鄙了吧！」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [85, "都子", "「世上哪有不卑鄙的大人啊？」", "myk001_010.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [86, "将臣", "「你还好意思一本正经地说出口？」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [87, "都子", "「就因为我是你妈，我才会告诉你真相啊。世界就是这么残酷」", "myk001_011.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [88, "都子", "「少废话了，赶紧去吧。也不想想你都几年没去看看你外公了」", "myk001_012.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [89, "都子", "「你小的时候外公那么照顾你，好歹得过去帮一次忙呀」", "myk001_013.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [90, "将臣", "「我这种外行，过去帮忙也只会添乱吧」", null, "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [91, "都子", "「怎么可能让你这种外行去招呼客人啊」", "myk001_014.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [92, "都子", "「除草，打扫浴池，倒垃圾，洗盘子，杂活多了去了」", "myk001_015.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [93, "都子", "「你整个春假都待在家里游手好闲，你觉得像话吗。行了赶紧过去！」", "myk001_016.ogg", "空_青空", "bgm01.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [94, "将臣", "「就是这么回事。我妈竟然这样威胁自己儿子，你不觉得这很卑鄙吗？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [95, "芦花", "「确实有点」", "rok001_013.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [96, "芦花", "「但谁让你这么多年一直不过来的，这是你自找的嘛」", "rok001_014.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "12"}], [97, "将臣", "「好吧……确实是太久没来了」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "12"}], [98, "芦花", "「你现在就去志那都庄吗？」", "rok001_015.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [99, "将臣", "「是的」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [100, "芦花", "「那我跟你一起去吧。这么久没见了，边走边聊会儿吧」", "rok001_016.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [101, "将臣", "「我没问题呀。不过，你那边时间不要紧吗？」", null, "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [102, "芦花", "「没事没事。咱们走吧」", "rok001_017.ogg", "街_雰囲気モブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [103, "将臣", "「……」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "25"}], [104, "芦花", "「……阿将，为什么我总感觉你一直在盯着我看？」", "rok001_018.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [105, "芦花", "「你这样盯着姐姐看，姐姐会害羞的。怎么，难道是迷上人家了吗？」", "rok001_019.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "11"}], [106, "芦花", "「还是说我脸上沾了什么东西？」", "rok001_020.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [107, "将臣", "「说实话，我确实是看入迷了」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [108, "芦花", "「———！？」", "rok001_098.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "25h"}], [109, "芦花", "「呃……那什么……啊哈哈，谢谢」", "rok001_099.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "07h"}], [110, "", "芦花姐可能觉得我在开玩笑……但我说的是真心话。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [111, "", "她的确出落得十分漂亮。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [112, "将臣", "「你眼睛下面沾了沙子」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [113, "芦花", "「这是泪痣好吗！」", "rok001_021.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "30"}], [114, "将臣", "「开玩笑啦，开玩笑」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "30"}], [115, "芦花", "「拿别人的身体特征开玩笑可不是什么好事」", "rok001_022.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "29"}], [116, "将臣", "「你不喜欢泪痣吗？抱歉，太久不见没把握好分寸」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "29"}], [117, "将臣", "「我就是有点害羞。放心吧，我觉得你的泪痣很可爱」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "29"}], [118, "芦花", "「真是的……都这么多年交情了，现在有什么害羞的嘛」", "rok001_023.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [119, "", "虽然芦花姐的笑容还是跟小时候一样和蔼可亲，但我难免觉得有些害羞。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [120, "", "毕竟……芦花姐真的非常漂亮。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [121, "", "尽管小时候并没有特意把她当成异性来看待，可到了这个年纪……多少还是会有点心跳加速。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [122, "", "虽然这话我不会说出来。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [123, "芦花", "「行了，跟我说实话吧，是有什么在意的地方吗？」", "rok001_024.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [124, "将臣", "「也不是什么大不了的事」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [125, "将臣", "「就是想起来，你以前穿的好像也是这种类型的衣服」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [126, "芦花", "「嗯？有什么奇怪的吗？虽然确实跟别人穿的那种时髦又可爱的衣服不太一样……」", "rok001_025.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "11"}], [127, "", "芦花姐一脸疑惑，似乎不觉得自己穿的衣服有什么问题。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [128, "", "当然了，这类衣服并不是她的个人爱好，在穗织长大的人都穿着这类衣服。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [129, "", "就像民族服饰一样。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [130, "", "虽然，这年头把这种衣服当常服穿的地区已经很少了。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [131, "", "据说这独特的服装也是小镇出名的原因之一，它给人一种世外桃源的感觉。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [132, "将臣", "「我只是单纯觉得你穿着很好看，没别的意思」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [133, "芦花", "「好吧。主要是我也不了解外面的世界，心里还是有点没底」", "rok001_026.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "32"}], [134, "将臣", "「你已经不是学生了吧？没考虑过去外面找工作吗？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "32"}], [135, "芦花", "「这年头工作哪有那么好找」", "rok001_027.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "26"}], [136, "将臣", "「那你现在在干什么呢？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "26"}], [137, "芦花", "「我家不是开了个店吗，你还记得吗？」", "rok001_028.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [138, "将臣", "「好像是咖啡屋来着？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [139, "芦花", "「是和式甜品屋，虽然也差不多就是啦。我现在在给家里帮忙……也不是帮忙吧，现在主要是我在负责经营」", "rok001_029.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [140, "将臣", "「呃，难不成叔叔阿姨他们……」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [141, "芦花", "「啊，不是不是，他们身体可好了。后场的工作他们都在干」", "rok001_030.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [142, "芦花", "「只是最近外国人游客越来越多，所以甜品屋的营业没法像以前那样了」", "rok001_031.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "28"}], [143, "芦花", "「我爸妈不懂的问题也是越来越多，后来就干脆把店全权交给我负责了」", "rok001_032.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "23"}], [144, "将臣", "「喔……这么说的话，你现在岂不是没工夫跟我在这里闲聊？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "23"}], [145, "芦花", "「微服私访来街上逛逛，顺带调查一下顾客的需求。这也是工作的一部分」", "rok001_033.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [146, "芦花", "「这就是所谓的硬性营销！」", "rok001_034.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [147, "将臣", "「是隐性营销吧」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [148, "将臣", "「好吧，有个人陪我说话也挺好的」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [149, "将臣", "「话说芦花姐，这里游客也太多了吧？虽然现在是春假期间」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [150, "", "路上到处都是人，还有人拖着大件行李，我们根本没法随意走动。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [151, "将臣", "「以前也是这么多人吗？我记得以前没有这么多吧……」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [152, "", "跟我小时候比起来，感觉现在游客多了不少。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [153, "", "照理说，在这附近长大的人一般都不愿意来这地方，就像刚才那位司机一样……", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [154, "芦花", "「整体来说游客确实变多了。毕竟现在网络上信息传播得太快了」", "rok001_035.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "19"}], [155, "芦花", "「据说咱们这里还登上了国外的网站，被介绍成“不为人知的温泉旅游胜地”，所以就越来越出名了」", "rok001_036.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "15"}], [156, "芦花", "「而且，今天是“春日祭”，应该有不少人是冲着这个来的」", "rok001_037.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [157, "将臣", "「啊，春日祭！原来今天是春日祭啊……我好像从来没逛过」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [158, "芦花", "「啊？没逛过吗？」", "rok001_038.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [159, "将臣", "「以前都是错开了旅游高峰期过来的」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [160, "将臣", "「逛春日祭的人很多吗？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [161, "芦花", "「呃……还好吧？单看客流来源的话，欧美的游客比例在逐渐增加」", "rok001_039.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [162, "芦花", "「春日祭上，会有男人穿着甲胄骑着马，在街道上游行」", "rok001_040.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "09"}], [163, "将臣", "「我记得……这里的春日祭好像起源于战国时期的某一场战争吧？」", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "09"}], [164, "芦花", "「咳咳。距今数百年前，天下大乱，战火纷飞，各路枭雄割据一方。就在当时，不知从哪冒出来一位奇异女子」", "rok001_041.ogg", "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [165, "", "芦花姐突然开始讲故事了。", null, "街_目抜き通りモブa", "bgm01.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [166, "芦花", "「这女子依附权势，集万千宠爱于一身，还蛊惑男人，引起纷争。她的真面目，乃是一只妖怪」", "rok001_042.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "24"}], [167, "芦花", "「也不知邻国的大名被那妖女灌了什么汤什么药，他竟野心膨胀，要来攻打穗织！」", "rok001_043.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "06"}], [168, "芦花", "「对方精通妖术，我方自然是陷入劣势。但就在沦陷前的那一刻，人们绝望之际的祈祷突然显灵了」", "rok001_044.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "03"}], [169, "芦花", "「老天爷赐给了穗织一把对抗妖力的神刀——丛雨丸」", "rok001_045.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "02"}], [170, "芦花", "「人们用神刀的力量打败了妖怪，战胜了邻国的大军。就这样，穗织这片土地又重新迎来了和平」", "rok001_046.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "02"}], [171, "芦花", "「锵锵♪」", "rok001_047.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [172, "芦花", "「穗织的春日祭，就是为了纪念这场战争的胜利。之所以要穿着甲胄游行，也是在模仿当年凯旋的士兵们」", "rok001_048.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "19"}], [173, "芦花", "「最后，巫女大人还会在神社献舞」", "rok001_049.ogg", "街_目抜き通りモブa", "bgm21.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [174, "芦花", "「啊，对了对了。还有传言说，跟妖怪大战之后，地面被撕裂，于是涌出了温泉」", "rok001_050.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [175, "将臣", "「这传得也太玄乎了吧？」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [176, "芦花", "「哈哈，确实。应该也没几个人真的相信这些」", "rok001_051.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [177, "芦花", "「不过，这种简单易懂的传说可是很重要的哦。尤其是对外国人来说」", "rok001_052.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "19"}], [178, "芦花", "「这里可是神秘的东方国度——日本」", "rok001_053.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [179, "将臣", "「是这样吗？」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [180, "芦花", "「毕竟这世上，有名的旅游胜地多了去了」", "rok001_054.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [181, "芦花", "「就算武器再怎么寒酸，有也总比没有好吧？」", "rok001_055.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [182, "将臣", "「话是这么说……不过你可是本地人，说寒酸什么的不太合适吧」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [183, "芦花", "「重要的是怎么把这个传说利用好。要用好的点子来支撑」", "rok001_056.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "14"}], [184, "芦花", "「过去还有伟人说过，“性能差别并不是战力差别的决定因素”」", "rok001_057.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [185, "将臣", "「那是某个机器人动画里的伟人吧」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [186, "芦花", "「反正，从外部招揽游客也是非常重要的啦」", "rok001_058.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [187, "将臣", "「是不是因为……这附近的人们都不太愿意来？」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [188, "", "听了我的疑问，芦花姐面露苦笑，摇了摇头。", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "28"}], [189, "芦花", "「何止不愿意来。打的时只要一说目的地是穗织，司机肯定不会给你好脸色，好多客人都抱怨这个」", "rok001_059.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "26"}], [190, "芦花", "「而且也不给增加新的公交线路」", "rok001_060.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "32"}], [191, "芦花", "「我们都申请过很多次了……但人家就是不愿意搭理」", "rok001_061.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "31"}], [192, "将臣", "「……」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "31"}], [193, "司机", "「竟然专门跑到这犬魂作祟之地来看庆典，最近不怕死的人也是越来越多了……」", "uts001_007_ref.ogg", "街_雰囲気a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [194, "", "那句话又浮现在脑海里。", null, "街_雰囲気a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [195, "", "周围的人们依然对穗织抱有不少偏见，对于这片土地也是敬而远之。", null, "街_雰囲気a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [196, "", "在封建迷信盛行的过去，这里甚至遭到了周边地区的排斥。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [197, "", "这主要都是因为芦花姐刚才讲的妖怪传说。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [198, "", "人们都说这里还残留着妖怪的怨念，要是随意靠近，就会被卷入灾厄之中，甚至丢掉性命。于是这样的迷信就被一代代传了下来。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [199, "", "不过到了今天，穗织的人们反而开始利用这些传言来招揽游客。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [200, "", "那位司机说的“犬魂作祟”就是指这里的诅咒，也是对这里的蔑称。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [201, "", "为什么交通一直这么不方便呢？", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [202, "", "为什么会被时代的大潮甩在身后呢？", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [203, "", "想必都是因为这里不仅无法借助外力，甚至连地区交流都很少，于是只能自给自足生活下去了。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [204, "", "多亏了温泉的功效，前来温泉疗养的游客倒是络绎不绝。但据说以前的客人，都是遮着脸来泡温泉的。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [205, "", "对当时的人来说，要是被发现自己泡了犬魂作祟之地的温泉，还是会有些麻烦的。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [206, "", "虽然那些负面印象也在渐渐消退……但对于在附近地区长大的本地人来说，成见还是难以消除。", null, "空_青空", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [207, "芦花", "「行啦，难得见一次，就别聊这些丧气的话了」", "rok001_062.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "02"}], [208, "芦花", "「机会难得，要不要一起去看看游行？」", "rok001_063.ogg", "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [209, "将臣", "「嗯……算了吧。我先去外公那里打个招呼」", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [210, "", "而且，我有可能今天就该过去帮忙了。", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [211, "", "我应该先去露个面才对。", null, "街_目抜き通りモブa", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [212, "", "我和芦花姐边走边聊，走了大约十五分钟。", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [213, "将臣", "「哎呀……这里真是跟以前一模一样」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [214, "芦花", "「玄十郎先生的旅馆生意可火爆了。不仅服务态度非常好，饭菜也很好吃」", "rok001_064.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "15"}], [215, "芦花", "「建筑也是古香古色，外国人都喜欢这种」", "rok001_065.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [216, "将臣", "「……」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [217, "", "终于要跟外公打招呼了……", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [218, "", "我的外公哪怕站在那不动，也会让人感到一股压力。我小时候非常害怕他。", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [219, "", "也许是因为小时候的记忆吧，我现在也不太敢跟他说话。", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [220, "将臣", "「打扰一下」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [221, "心子", "「您稍等，马上就来」", "mot001_001.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [222, "心子", "「让您久等了。请问是预约过的客人吗？」", "mot001_002.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [223, "将臣", "「抱歉打扰了，我不是客人。请问鞍马玄十郎在吗？」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [224, "心子", "「不好意思，请问……」", "mot001_003.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [225, "将臣", "「我想先给外公打个招呼」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [226, "心子", "「您就是大当家的外孙吧，我听他老人家说了。感谢您大老远过来帮忙」", "mot001_004.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [227, "心子", "「大当家现在正在建实神社那边，他是执行委员」", "mot001_005.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [228, "芦花", "「啊，是这样啊。原来玄十郎先生是春日祭的执行委员」", "rok001_066.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [229, "心子", "「如果游行按照计划进行……现在应该差不多到神社了」", "mot001_006.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "08"}], [230, "芦花", "「那他暂时应该没法离开神社」", "rok001_067.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "09"}], [231, "将臣", "「是吗」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "09"}], [232, "将臣", "「请问，现在有什么我可以帮忙的吗？」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [233, "心子", "「感谢您的好意」", "mot001_007.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [234, "心子", "「不过现在还不那么忙，所以您今天就好好享受春日祭吧」", "mot001_008.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [235, "将臣", "「那就恭敬不如从命了」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [236, "心子", "「需要我帮您把行李拿进去吗？」", "mot001_009.ogg", "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [237, "将臣", "「好的，麻烦您了。谢谢」", null, "旅館_旅館前a", "bgm05.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [238, "将臣", "「芦花姐，我外公现在还精神吗？」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [239, "芦花", "「那当然了。他从来不感冒，背一点也不弯，腰腿也好得很」", "rok001_068.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [240, "芦花", "「而且好像还在每天坚持用木刀练素振」", "rok001_069.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [241, "将臣", "「是吗……他还是这么精神啊……当然了，这是好事」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [242, "芦花", "「你呢？还在练剑道吗？」", "rok001_070.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [243, "将臣", "「已经没练了。都快两年没握过木刀了」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [244, "芦花", "「为什么呀？」", "rok001_071.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [245, "将臣", "「本来就是外公让我练我才练的。他说什么对身体健康有好处」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [246, "将臣", "「但没人逼我之后我就不想练了……再加上学习又忙，最后压根都不碰木刀了」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "18"}], [247, "芦花", "「感觉就像自然而然分手的情侣一样啊」", "rok001_072.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [248, "将臣", "「比喻得太形象了」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [249, "将臣", "「所以，我现在都有点没脸见我外公……」", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [250, "芦花", "「他再怎么也不可能把你吃掉的啦」", "rok001_073.ogg", "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [251, "", "我知道自己有点害怕过头了。我也知道外公其实人很好。", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [252, "", "但年幼时被深深埋下的恐惧心理现在依然盘踞在心中……", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [253, "", "就怕他会大发雷霆，冲我大吼道：“你又给我做事半途而废！”", null, "街_小道a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [254, "", "神社院子里人山人海。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [255, "", "游客们摩肩接踵，一齐望着神乐殿。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [256, "", "其中有些人还举着相机或是手机。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [257, "芦花", "「哇，我们好像正赶上巫女大人献舞呢」", "rok001_074.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [258, "将臣", "「我看看，外公是在里面吗？」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [259, "芦花", "「阿将，阿将。你别这么不感兴趣嘛，去看看神乐舞吧？」", "rok001_075.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [260, "芦花", "「巫女大人的神乐舞跳得可好了」", "rok001_076.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [261, "芦花", "「游客们也都很喜欢看她跳舞。这是春日祭的一大看点之一呢」", "rok001_077.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "02"}], [262, "芦花", "「来吧来吧，你这个身高站在这里应该就能看见了吧」", "rok001_078.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [263, "", "听了芦花姐这么说，我也顺着大家的视线望了过去。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [264, "", "随后——", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [265, "将臣", "「……」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [266, "", "我不由得看呆了。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [267, "", "正在献舞的巫女，大概跟我同岁。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [268, "", "她舞姿绮丽，动作优雅。长发轻拂，衣袖翩翩。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [269, "", "这一切，都传递着一种美感。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [270, "", "看入迷的人似乎不只是我。四周的嘈杂声也渐渐消失。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [271, "", "不仅是观众的声音，甚至连鞋底砂子摩擦的声音都被寂静所吞没。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [272, "", "只留下神乐铃那清脆的响声在舞台上回荡，余音绕梁久久不能散去。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [273, "", "她的舞蹈就是如此美丽，美得让人不忍心错过任何一瞬。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [274, "", "这种感觉简直如同身体被控制了一样。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [275, "", "舞步之中，仿佛透着一股不可思议的力量……", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [276, "将臣", "「（这……确实很值得一看」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [277, "", "那优雅的舞姿，看上去简直就像仙女——", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [278, "将臣", "「！？！？」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [279, "", "什、什么情况……？仙、仙女头顶上，长出了耳朵……？", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [280, "将臣", "「……咦？」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [281, "", "刚才我明明看到类似兽耳一样的东西长了出来呀……现在却看不见。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [282, "", "我擦了擦眼睛，又确认了一遍。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [283, "", "还是没看见有什么兽耳。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [284, "将臣", "「……？……？？？」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [285, "芦花", "「阿将？」", "rok001_079.ogg", "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [286, "将臣", "「没、没什么」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [287, "", "是我看错了吗……难道是太累了？", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [288, "", "也、也是。今天算上换乘，一共坐了两个小时电车。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [289, "", "肯定是太累了。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [290, "", "而且其他游客都表现得很正常。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [291, "将臣", "「应该……是我看错了吧」", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [292, "", "人的头顶上怎么可能长出耳朵呢。", null, "神社_境内a", "bgm26.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [293, "芦花", "「怎么样？巫女大人的神乐舞跳得好吧」", "rok001_080.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [294, "将臣", "「非常优美。我都有点后悔自己没有从头开始看了」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [295, "芦花", "「不止春日祭，办祭祀活动的时候也能看到巫女大人跳舞，以后机会多着呢」", "rok001_081.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "15"}], [296, "芦花", "「那现在我们就去玄十郎先生那里？」", "rok001_082.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [297, "将臣", "「对哦……我是来跟外公打招呼的」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [298, "芦花", "「他应该还在这里……啊！」", "rok001_083.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "03"}], [299, "芦花", "「廉太郎！小春！」", "rok001_084.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [300, "廉太郎", "「嗯？怎么了，芦花姐」", "ren001_001.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [301, "小春", "「怎么了，姐姐」", "koh001_001.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [302, "", "听见芦花姐的声音后，二人转过身来。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [303, "廉太郎", "「等等……哎？你是将臣？」", "ren001_002.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [304, "小春", "「啊，真的耶！哥哥！」", "koh001_002.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [305, "", "看见我之后大吃一惊的，是鞍马廉太郎和她的妹妹鞍马小春。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [306, "", "他们俩是外公的孙子，也就是我的表亲。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [307, "", "他们的父亲就是我妈的哥哥，也就是我的舅舅。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [308, "", "顺便一提，虽然舅舅是长子，但是并没有继承旅馆，而是在别处工作。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [309, "将臣", "「好久没见你们了啊」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [310, "廉太郎", "「真的好久没见了！是什么风把你吹来了啊，这几年一直都没来过，这次是怎么了？」", "ren001_003.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [311, "将臣", "「外公的旅馆人手不够，我过来帮忙呢」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [312, "小春", "「哥哥是来帮忙的吗？我还以为跟往年一样，是姑姑过来帮忙呢」", "koh001_003.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [313, "将臣", "「因为我太久没来了。所以我妈逼着我过来露个脸」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [314, "小春", "「真的是很久没见了嘛。这几年你一直都没回来过」", "koh001_004.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [315, "小春", "「你现在长得好高，一开始我都没认出来是谁呢」", "koh001_005.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [316, "将臣", "「小春也长大了不少呀，跟以前比都大变样了」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [317, "小春", "「真、真的？哈哈……哥哥这么说我好开心」", "koh001_006.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [318, "廉太郎", "「肯定是哄你的啊。你那胸部哪里长大了」", "ren001_004.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [319, "小春", "「长、长了好吗！跟去年比起来大了整整０．２毫米！」", "koh001_007.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [320, "廉太郎", "「这都是误差，是误差好吗」", "ren001_005.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [321, "小春", "「廉哥你烦不烦！能闭嘴吗」", "koh001_008.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [322, "将臣", "「廉太郎是天天看着小春，所以根本看不出来吧」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [323, "小春", "「哥哥，你太会说话了，我好感动……！」", "koh001_009.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [324, "小春", "「哥哥，你要是我的亲哥哥该多好啊，我才不想要这个蠢蛋哥哥」", "koh001_010.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [325, "廉太郎", "「我还不想让你这讨厌鬼当我妹妹呢，我想要个更可爱更漂亮的妹妹」", "ren001_006.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [326, "小春", "「你再说一遍！」", "koh001_011.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [327, "廉太郎", "「你想怎么样？」", "ren001_007.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [328, "小春", "「笨蛋笨蛋」", "koh001_012.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [329, "廉太郎", "「丑八怪丑八怪」", "ren001_008.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [330, "芦花", "「行了，别闹了别闹了。兄妹吵架适可而止啊」", "rok001_085.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [331, "将臣", "「你们俩真是从小到大一直没变啊……」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [332, "", "这么多年，关系还是这么好。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [333, "芦花", "「话说回来，你们知道玄十郎先生在哪吗？」", "rok001_086.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [334, "廉太郎", "「爷爷现在就在里面」", "ren001_009.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [335, "小春", "「你忘了吗，现在在办那个活动」", "koh001_013.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "34"}], [336, "芦花", "「啊，那个啊」", "rok001_087.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [337, "将臣", "「？？？什么活动？」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "21"}], [338, "小春", "「就是传说中的勇者活动」", "koh001_014.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [339, "将臣", "「什么东西啊？」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [340, "芦花", "「就是这建实神社的神刀。你应该听说过的吧？」", "rok001_088.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [341, "将臣", "「神刀……啊，就是那个啊……我听说过，但是没见过实物」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "04"}], [342, "", "建实神社里供奉着一把特别的刀。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [343, "", "那样特别的刀只有这里才有，现在举办的活动也正是跟这把刀相关的。", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [344, "将臣", "「我记得是必须抽签抽中之后才能进去的吧？」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [345, "廉太郎", "「那都是外部游客」", "ren001_010.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [346, "廉太郎", "「你又不参加活动，只是去跟爷爷打招呼的话，是可以进去的」", "ren001_011.ogg", "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [347, "将臣", "「那我就先进去了」", null, "神社_境内a", "bgm01i.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [348, "", "我一走进神社便看到了排成长队的游客。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [349, "", "大约三十多人的长队一半以上都是男性，其中还有七八名女性。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [350, "", "而且这些人里面外国人特别多。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [351, "", "队伍的最前端，有一把刀。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [352, "将臣", "「还真是插在上面啊……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [353, "", "这里明明是室内，却摆着一块巨大的岩石。那把日本刀，就插在岩石的正中央。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [354, "", "美丽的刀身从岩石中伸出，闪耀着银色的光芒，十分夺目。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [355, "", "这把如同亚瑟王传说现代版一样的刀，就是这座神社供奉的神刀。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [356, "", "而现在正在举办的活动，名字就叫“有谁能拔出这把刀？！”", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [357, "廉太郎", "「你是第一次来神社吗？」", "ren001_012.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [358, "将臣", "「以前过年时去参拜过……也就仅此而已了」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [359, "将臣", "「这还是我第一次进里面来」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [360, "芦花", "「那把神刀，就是传说中降服了妖怪的“丛雨丸”哦」", "rok001_089.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [361, "将臣", "「真的拔不出来吗？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [362, "小春", "「拔不出来拔不出来。不管再怎么使劲都是纹丝不动」", "koh001_015.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "01"}], [363, "廉太郎", "「我也试过，根本拔不动。不管是往里按还是往外拔，根本动都不动」", "ren001_013.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [364, "廉太郎", "「然后我就恼火了，直接往两边掰，但它就是一动不动」", "ren001_014.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [365, "将臣", "「你别瞎搞啊，掰断了怎么办」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [366, "廉太郎", "「要是我这点力气都能掰断，那它怎么可能禁得住这么多次挑战啊」", "ren001_015.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [367, "将臣", "「话是这么说……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [368, "", "这个活动从很早以前就开始举办了，据说最开始任何人都可以随意尝试。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [369, "", "但是后来游客越来越多，神社忙不过来，于是改成了现在这种提前抽签的形式。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [370, "", "外国人游客……尤其是欧美游客，都特别喜欢这个活动。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [371, "", "此时，一群彪形大汉正在挑战。只见他们那满面天真的笑容渐渐消失，随着施力而鼓起的脸颊越涨越红。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [372, "外国人の観光客Ａ", "「哼，唔唔唔唔唔唔——————！」", "gka001_001.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [373, "外国人の観光客Ｂ", "「嗯————————！唔唔唔！」", "gkb001_001.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [374, "外国人の観光客Ｃ", "「哼，嗯嗯嗯啊————！啊噢噢噢噢噢噢噢噢！！！」", "gkc001_001.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [375, "", "然而没有一个人能拔出来。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [376, "", "哪怕是上臂快有我大腿那么粗的肌肉男，也没法让神刀移动分毫。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [377, "廉太郎", "「你一时半会难以相信，我也理解。但是你觉得这群使出了吃奶的力气的肌肉男，像是在作假吗？」", "ren001_016.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [378, "芦花", "「我们也从来没听说过作假之类的事。要是敢瞎说，还会被爸妈骂的」", "rok001_090.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [379, "小春", "「而且我觉得，爷爷那性格肯定很讨厌弄虚作假」", "koh001_016.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [380, "将臣", "「那确实」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [381, "", "就算他可能会为了小镇着想，不把事情说出来，但绝对不会亲自帮忙。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [382, "", "也就是说……这个活动是真的………………", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [383, "将臣", "「哎，也罢」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [384, "", "不管怎么说，都跟我无关。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [385, "", "赶紧办正事吧。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [386, "将臣", "「——啊，找到了」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [387, "玄十郎", "「……」", "gen001_001.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [388, "", "只见外公正静静地观望着挑战的过程，表情还是一如既往地严肃。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [389, "", "我慢慢地朝他那边走了过去。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [390, "将臣", "「好久不见了。我是将臣」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [391, "玄十郎", "「嗯」", "gen001_002.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [392, "将臣", "「……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [393, "", "压力好大啊……", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [394, "将臣", "「我是来给旅馆帮忙的。我也不确定自己能不能做好，这段时间就麻烦你们多多指教了」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [395, "玄十郎", "「大老远的，也累了吧。这段时间要辛苦下你了。你可以明天再开始帮忙，今天就好好休息吧」", "gen001_003.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [396, "将臣", "「好的」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [397, "玄十郎", "「这几年过得怎么样？」", "gen001_004.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [398, "玄十郎", "「身体还好吧？没有生病什么的吧？」", "gen001_005.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [399, "将臣", "「嗯，身体很好」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [400, "玄十郎", "「听说你已经不练剑道了」", "gen001_006.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [401, "将臣", "「这个……是的」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [402, "玄十郎", "「没事，只要身体健康就行。本来让你练剑道就是为了锻炼身体」", "gen001_007.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [403, "玄十郎", "「总之，这段时间要辛苦下你了。有什么事尽管说，千万不要勉强自己」", "gen001_008.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [404, "将臣", "「谢谢外公」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [405, "", "……呼。总算是打完招呼了。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [406, "", "外公明明已经年过古稀，但从他的气色中却完全看不到衰老的迹象……真是可怕。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [407, "玄十郎", "「……」", "gen001_009.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [408, "将臣", "「那什么，有个问题想问下……那把刀是真的插在石头里吗？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [409, "玄十郎", "「你不知道这里的传说吗？」", "gen001_010.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [410, "将臣", "「知道倒是知道……但是，那就是一把刀吧？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [411, "玄十郎", "「那不是一般的刀，是天神赐予的」", "gen001_011.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [412, "将臣", "「……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [413, "玄十郎", "「你不相信我也可以理解，但确实没有作假」", "gen001_012.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [414, "将臣", "「那它真的可以拔出来吗？感觉完全动都不动啊」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [415, "玄十郎", "「单纯靠力气是拔不出来的」", "gen001_013.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [416, "将臣", "「那是有什么窍门吗？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [417, "玄十郎", "「……也不是窍门……需要的是资格」", "gen001_014.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [418, "将臣", "「……？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [419, "", "这是什么意思？", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [420, "玄十郎", "「对了……将臣，你拔过没？」", "gen001_015.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [421, "将臣", "「我还是第一次看这活动」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [422, "玄十郎", "「这样啊……」", "gen001_016.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [423, "玄十郎", "「那刚好。一会儿你也去试试吧」", "gen001_017.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [424, "将臣", "「哎？我去拔？我没有提前报名来着」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [425, "玄十郎", "「没问题。我去说一下就行了。你稍微等等」", "gen001_018.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [426, "", "还没等我答应，外公就走到了一个神主打扮的人旁边，开始跟他交谈。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [427, "", "外公真的想让我挑战吗。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [428, "廉太郎", "「怎么了？什么情况？」", "ren001_017.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [429, "将臣", "「外公突然说让我去挑战一下」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [430, "将臣", "「为什么要让我挑战啊……要是没拔出来，他会生气吗……？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [431, "芦花", "「那怎么可能呢。你就随便去拔一下就行了吧？」", "rok001_091.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [432, "小春", "「我跟廉哥也去拔过的，爷爷应该没有别的意思」", "koh001_017.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [433, "廉太郎", "「说起来我们确实去拔过」", "ren001_018.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "17"}], [434, "廉太郎", "「我也觉得你不用想太多。我跟小春都没拔出来，也没见他老人家说什么」", "ren001_019.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [435, "小春", "「哥哥，你不用这么害怕爷爷的啦」", "koh001_018.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [436, "将臣", "「毕竟这么久没见，我对外公的印象还停留在小时候」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [437, "廉太郎", "「这个嘛，我理解你的感受。他也骂过我很多次……」", "ren001_020.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [438, "小春", "「还不是因为你净干蠢事。我就没怎么被爷爷骂过」", "koh001_019.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [439, "芦花", "「确实……廉太郎太淘气了。不管是小时候，还是现在……哈哈」", "rok001_092.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "10"}], [440, "小春", "「我不用想就知道，你今天肯定又去搭讪泡妞了吧，而且专找游客下手」", "koh001_020.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [441, "廉太郎", "「——唔！？」", "ren001_021.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [442, "芦花", "「啊，果然没错。然后呢，战果如何？」", "rok001_093.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "11"}], [443, "廉太郎", "「……没人理我」", "ren001_022.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "11"}], [444, "芦花", "「试了几次？」", "rok001_094.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "10"}], [445, "廉太郎", "「大概１３次？」", "ren001_023.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "10"}], [446, "将臣", "「这么多次啊！而且全部无功而返！」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "10"}], [447, "小春", "「说明廉哥也就这点本事了」", "koh001_021.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [448, "廉太郎", "「瞎说！别瞧不起人啊！就算我成功率低，偶尔也是能钓到大鱼的！」", "ren001_024.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [449, "将臣", "「廉太郎竟然跑去搭讪……小时候明明那么土气」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [450, "廉太郎", "「所以现在才想放飞自我」", "ren001_025.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [451, "芦花", "「玄十郎先生都骂了你多少次了，你也真是不长记性」", "rok001_095.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [452, "廉太郎", "「是爷爷管得太严了好吗。这年头搭个讪有什么奇怪的」", "ren001_026.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [453, "廉太郎", "「这小地方来来回回就那几个女生，我必须积极地去认识外面的人啊」", "ren001_027.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [454, "将臣", "「……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [455, "", "听他的口气……感觉他好像已经是情场老将了？", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [456, "", "想着想着……一股挫败感油然而生。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [457, "将臣", "「唉，廉太郎都学会搭讪了……」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [458, "", "小时候还整天跟我一起认认真真地练剑呢……", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [459, "", "真的是光阴似箭。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [460, "玄十郎", "「将臣！」", "gen001_019.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [461, "将臣", "「啊，来了」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [462, "玄十郎", "「征得同意了，你过来吧」", "gen001_020.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [463, "", "不知不觉，排队的人群已经全部挑战结束。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [464, "", "室内就剩下外公和我们几个，以及那位神主打扮的男性。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [465, "", "现在，所有人的视线都集中在我身上，真的是相当紧张……", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [466, "", "赶快挑战赶快结束吧。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [467, "", "要想摆脱被众人瞩目的现状，这是最快的方法。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [468, "将臣", "「有什么礼仪上的规矩吗？」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [469, "玄十郎", "「这个……倒没有什么特别的要求，但你还是行个礼吧」", "gen001_021.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [470, "", "我站在神刀前，轻轻鞠了一躬。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [471, "", "就在我伸出双手，紧紧握住刀柄的那一刻——", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [472, "", "一股触电般的感觉，从指间传遍全身。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [473, "", "静电……？日本刀还有静电？我摸的明明是刀柄啊……？", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [474, "玄十郎", "「怎么了？」", "gen001_022.ogg", "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [475, "将臣", "「啊，没，没什么」", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [476, "", "我再一次面向这把刀。", null, "神社_神社内（刀）a", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [477, "将臣", "「那么，我就……」", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [478, "", "赶快完事儿吧。", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [479, "", "为了不手滑，我紧紧地将刀柄握住。", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [480, "", "……比想象中更硬。", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [481, "", "不过，我还是得认真点拔，要是太随意了外公可能会生气。", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [482, "将臣", "「——唔」", null, "神社_神社内（刀）a", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [483, "芦花", "『哇』", "koh001_022.ogg", "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [484, "廉太郎", "「不是吧」", "ren001_028.ogg", "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [485, "将臣", "「……嗯……？」", null, "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [486, "", "刚才那坚硬的触感就像是个玩笑一样。", null, "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [487, "", "神刀竟然轻而易举地离开了岩石。", null, "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [488, "", "然而，刀尖部分却依然插在岩石之中。", null, "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [489, "将臣", "「………………」", null, "神社_神社内a", "bgm25.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [490, "将臣", "「……啊？」", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [491, "", "……断了？", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [492, "", "我试着将神刀拼回原来的位置……好吧，怎么可能复原呢。", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [493, "将臣", "「啊，啊，啊，啊，啊……哈哈哈哈」", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [494, "将臣", "「哈哈哈哈哈啊，太搞笑了，这什么情况，哈哈哈哈哈，太逗了吧」", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [495, "将臣", "「哎，廉太郎，你来看看。来来，你拿着试试」", null, "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [496, "廉太郎", "「喂，你不要给我啊！别过来！这事儿跟我没关系！」", "ren001_029.ogg", "神社_神社内a", "bgm22.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [497, "将臣", "「不不不，是你亲口告诉我的啊！你说这刀坚固得很，怎么拔也拔不动！」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [498, "廉太郎", "「确实是我说的！\\n但是没让你真折断啊！有谁会真的折断啊！？」", "ren001_030.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [499, "将臣", "「我根本没想折断啊，说到底我根本就没有用力好吗！」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [500, "廉太郎", "「不管你怎么说，你手上拿的东西就是现实。认命吧」", "ren001_031.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [501, "将臣", "「这是整人节目吧？肯定是整人节目吧？你们是在整我吧！？」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [502, "廉太郎", "「不知道不知道。我什么都不知道！」", "ren001_032.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [503, "将臣", "「求你了，你就告诉我这是整人节目吧」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [504, "廉太郎", "「都说了我不知道！不要拖我下水啊！」", "ren001_033.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [505, "", "神刀干脆利落地断成了两截，拿在我手上的只有短短一截。", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [506, "", "但依然还是有点分量……这就是现实……不是梦或者幻觉。", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [507, "廉太郎", "「啊……差不多该回去吃晚饭了」", "ren001_034.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "20"}], [508, "芦花", "「啊……我也该回去了……还有工作要忙」", "rok001_097.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "芦花.stand", "dress": "私服", "face": "22"}], [509, "小春", "「啊……我还有作业没做完……」", "koh001_023.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [510, "将臣", "「等等，不要丢下我啊！我不想一个人扛雷啊！」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [511, "玄十郎", "「……」", "gen001_023.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [512, "将臣", "「啊」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [513, "玄十郎", "「………………」", "gen001_024.ogg", "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [514, "将臣", "「啊啊啊啊啊啊啊！！！」", null, "神社_神社内a", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [515, "将臣", "「……」", null, "空_夜空", "bgm24.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [516, "将臣", "「我……接下来会被怎么样啊……？」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [517, "", "正当我不知所措时，外公让我在原地等着，然后不知道跑哪去了。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [518, "", "芦花姐她们也都回去了……准确地说，是外公让她们回去的。现在这里就剩我一个人。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [519, "将臣", "「……」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [520, "将臣", "「我好慌……我好慌啊……」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [521, "", "在那之后，外公不停地嘀咕着什么“没想到会发生这种事……”“没想到真的出现了……”之类的话。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [522, "", "看来他也完全没料到这种事。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [523, "", "那也是理所当然的。毕竟这可是穗织镇招揽客游客的重要活动之一……", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [524, "", "而我却把这活动搞没了。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [525, "将臣", "「啊啊啊啊啊啊啊啊啊！完了！这下真的完了！」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [526, "", "他们会不会追究我折断神刀的责任啊？", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [527, "", "要追责的话，就得赔偿吧？不仅要赔偿神刀，还得赔偿活动无法举办带来的损失……这可绝对不是个小数目。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [528, "", "几千万？不，可能要赔好几亿吧？甚至更高……", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [529, "将臣", "「那么多钱……我根本赔不起」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [530, "", "也就是说……", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [531, "黒服Ａ", "「小哥，欠钱不还，这就有点说不过去了呀」", "kra001_001.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [532, "黒服Ｂ", "「你说还不起？你还不还得起，跟我们有什么关系呢」", "kfb001_001.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [533, "黒服Ａ", "「说到底，这都是你自己惹的祸吧？」", "kra001_002.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [534, "黒服Ｂ", "「那你就必须负责才行呀。所谓的负责就是这么一回事」", "kfb001_002.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [535, "黒服Ａ", "「不过……我看你现在也确实没钱」", "kra001_003.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [536, "黒服Ｂ", "「所以我们特意！特意为你准备了一份工作！」", "kfb001_003.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [537, "黒服Ａ", "「工作内容就是在地下造一座设施，只要你在那工作，就可以免除你的利息！」", "kra001_004.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [538, "黒服Ｂ", "「而且包吃包住，也不用外出，可以专心搞工作！工作之余，还有赌博之类的娱乐项目可以玩！」", "kfb001_004.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [539, "黒服Ａ", "「来吧，咱们快去吧，有地将臣先生！」", "kra001_005.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [540, "黒服Ｂ", "「来吧！来吧来吧！」", "kfb001_005.ogg", "空_夜空", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [541, "将臣", "「我不想去地下王国啊————！」", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [542, "", "我还是赶快溜吧……", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [543, "", "不，外公还在这里，我一个人逃了也没用。还是老老实实听从发落吧。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [544, "", "我内心充满了愧疚感，身体不由得就变成了正坐姿势。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [545, "将臣", "「……哎……」", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [546, "将臣", "「现在就算被骂我也无话可说。只求能快点告诉我怎么处置」", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [547, "", "在这安静的房间里，我静静等待外公归来。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [548, "", "就在这时，我听见了一位少女的声音。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [549, "ムラサメ", "「你，就是本座的主人？」", "mur001_001.ogg", "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [550, "将臣", "「……嗯？」", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [551, "", "有人……在说话。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [552, "", "但是室内……好像只有我一个人？", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [553, "ムラサメ", "「在这里，这里」", "mur001_002.ogg", "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [554, "", "声音是从头顶传来的。", null, "神社_神社内d", "bgm23.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [555, "将臣", "「哇啊啊！？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [556, "ムラサメ", "「哦？看你如此吃惊，想必是看得见本座，也能听见本座说话吧」", "mur001_003.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [557, "", "抬头望去，只见空中浮着一位少女。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [558, "", "她一边俯视着我，一边自由自在地让整个身体轻轻地漂浮在空中……她的脚下没有任何东西。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [559, "将臣", "「竟、竟然浮在空中……！是、是幽灵……！？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [560, "ムラサメ", "「才不是！本座决不是什么幽灵！」", "mur001_004.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [561, "将臣", "「可是，你……为什么浮在空中……」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [562, "ムラサメ", "「吾名丛雨，乃是这“丛雨丸”的管理者……简单来说，也算是“丛雨丸”的灵魂」", "mur001_005.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [563, "将臣", "「莫非，因、因为我折断了刀，所以你要找我报仇……？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [564, "ムラサメ", "「都说了，本座不是幽灵！」", "mur001_006.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [565, "ムラサメ", "「而且刀身断裂，根本无须复仇。这点小伤，丛雨丸立刻就能自愈」", "mur001_007.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [566, "将臣", "「呃，可是……这断得很彻底啊？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [567, "ムラサメ", "「百闻不如一见。本座这就让你开开眼界」", "mur001_008.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [568, "", "说罢，少女闭上了眼睛。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [569, "", "随后，折断的丛雨丸发出淡淡清光，徐徐上升。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [570, "", "从脚下到胸前，再到头顶，最后到达了和浮空少女平齐的高度。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [571, "", "面对眼前的光景，我惊得一句话都说不出来，只是目不转睛地望着少女。就在下一秒——", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [572, "将臣", "「哇啊……！？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [573, "", "刀身发出了炫目的白光，遮蔽了我的视野。一瞬间我甚至以为自己要失明了。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [574, "", "但是，这白光却一点也不刺眼，而是十分柔软，甚至给人一股暖意……", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [575, "", "不一会儿，白光渐渐淡去，视野也慢慢恢复了。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [576, "ムラサメ", "「你看，复原了」", "mur001_009.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [577, "将臣", "「不是吧……真的假的……？」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [578, "", "刚才还断成两半的刀，现在已经完全复原了。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [579, "", "我没有看错。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [580, "将臣", "「……」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [581, "", "少女能浮在空中，折断的刀还能恢复原状。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [582, "", "过度的惊讶，反而让我冷静了起来。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [583, "将臣", "「真、真的复原了……」", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [584, "ムラサメ", "「现在你能稍微静下心来听本座说话了吗？」", "mur001_010.ogg", "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [585, "", "少女一边说着，一边慢慢地从半空中降了下来。", null, "画面_黒", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [586, "ムラサメ", "「——着陆」", "mur001_011.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [587, "ムラサメ", "「吾名丛雨，乃是这“丛雨丸”的管理者，亦是司掌神力之人」", "mur001_012.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [588, "将臣", "「神力……？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [589, "ムラサメ", "「今后还请多多指教，主人」", "mur001_013.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [590, "将臣", "「呃，主人是什么意思啊……」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [591, "ムラサメ", "「怎么了？什么事让你如此震惊？」", "mur001_014.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [592, "将臣", "「现在这情况让我脑子一片混乱，根本不知道该怎么办才好」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [593, "将臣", "「我先确认下……你叫我“主人”是什么意思？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [594, "ムラサメ", "「主人就是主人。是你拔出了丛雨丸吧？」", "mur001_015.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [595, "将臣", "「拔倒是没拔出来，但是被我折断了」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [596, "ムラサメ", "「这都无所谓。总而言之，让丛雨丸离开那块岩石的人就是你吧？」", "mur001_016.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [597, "将臣", "「啊，嗯，是的」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [598, "ムラサメ", "「这并不是普通人能够做到的」", "mur001_017.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [599, "ムラサメ", "「无缘之人纵然使出浑身解数，也无法让丛雨丸挪动分毫」", "mur001_018.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [600, "ムラサメ", "「可是主人，你又如何？你拔刀时用力了吗？」", "mur001_019.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [601, "将臣", "「不，没有。我轻轻一扯，就断了」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [602, "", "那种感觉就像掰断泡沫板一样，易如反掌。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [603, "ムラサメ", "「这就是最好的证明。你是有资格使用丛雨丸的人」", "mur001_020.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [604, "将臣", "「可我还是有点……」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [605, "ムラサメ", "「主人，你到底在纠结什么？」", "mur001_021.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [606, "将臣", "「还能是什么………………」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [607, "将臣", "「好吧我知道了」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [608, "", "不，其实还有很多细节没搞清楚。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [609, "将臣", "「反正，我就是被选中了，是吧？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [610, "ムラサメ", "「目前可以这么理解」", "mur001_022.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [611, "将臣", "「那下一个问题。为什么断成两截的刀能一瞬间复原呢？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [612, "ムラサメ", "「丛雨丸乃神刀，是穗织的土地神赐予的宝刀，绝非凡品」", "mur001_023.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [613, "ムラサメ", "「哪怕生锈，缺损，折断，只要拜借神力，即可恢复原状」", "mur001_024.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [614, "将臣", "「也就是说……你是神刀的管理者，能够拜借神力？你叫什么来着……」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [615, "ムラサメ", "「吾名丛雨。都跟你说了两遍了吧」", "mur001_025.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [616, "将臣", "「你叫丛雨啊……」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [617, "ムラサメ", "「一上来就直呼本座大名啊，主人」", "mur001_026.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [618, "将臣", "「那……小雨？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [619, "ムラサメ", "「这称呼也太没威严了……也罢，随你了。毕竟你是本座的主人。那么，你还有什么问题？」", "mur001_027.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [620, "将臣", "「你刚才提到的司掌神力还有灵魂那些，能说得再详细一点吗」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [621, "ムラサメ", "「嗯，你听好了。丛雨丸蕴含着神力，是一把用来和妖力对抗的神刀」", "mur001_028.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [622, "ムラサメ", "「但是，神力很难依附在单纯的铁器上。若要依附神力，不可或缺的是人的灵魂」", "mur001_029.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [623, "ムラサメ", "「神力附于灵魂，灵魂宿于刀身，这才有了神刀丛雨丸。而丛雨丸的灵魂正是本座」", "mur001_030.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [624, "将臣", "「你是灵魂……稍等一下」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [625, "将臣", "「也就是说，你为了让丛雨丸获得神力，牺牲了自己？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [626, "ムラサメ", "「嗯。你的理解没问题」", "mur001_031.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [627, "将臣", "「这么说你果然是……幽、幽灵……！？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [628, "ムラサメ", "「本座才不是幽灵！完全不是！不要把幽灵和本座相提并论！」", "mur001_032.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [629, "ムラサメ", "「本座是丛雨丸的管理者！是神的使者，也就是所谓的神使！」", "mur001_033.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [630, "ムラサメ", "「哪是什么幽灵，别……别别别把本座和那种毫无事实依据的东西混为一谈」", "mur001_034.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [631, "将臣", "「你说这话之前就没想过自己的情况吗！」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [632, "将臣", "「刚才说的这些都太玄乎了……反正，你成为了神使之后，就只剩下灵魂了吗？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [633, "ムラサメ", "「嗯，可以这么说」", "mur001_035.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [634, "", "怎么想都是幽灵啊……", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [635, "ムラサメ", "「但也正因如此，本座无法影响现世，不能亲自使用神刀」", "mur001_036.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [636, "ムラサメ", "「所以就需要一位能够使用丛雨丸的人，也就是本座的主人」", "mur001_037.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [637, "将臣", "「就是指我吧」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [638, "ムラサメ", "「只有被选中的人才能使用丛雨丸」", "mur001_038.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [639, "ムラサメ", "「而你已被丛雨丸选中，所以才能看见本座，和本座说话」", "mur001_039.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [640, "将臣", "「其他的人都看不到你，也听不到你的声音吗？」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [641, "ムラサメ", "「嗯，不过也有个别例外」", "mur001_040.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [642, "ムラサメ", "「顺便一提，即便是主人你，也无法触碰本座」", "mur001_041.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [643, "将臣", "「是吗？我明明看得这么清楚」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [644, "ムラサメ", "「就算试着接触本座也会从身体中间穿过去，就像这样」", "mur001_042.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [645, "", "小雨把手伸向丛雨丸的刀柄。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [646, "", "但是，她那小小的手掌不仅什么都没抓住，还从刀柄中穿了过去。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [647, "ムラサメ", "「主人，要不你也来试试？来吧，想摸哪里都可以」", "mur001_043.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [648, "", "说着，小雨挺起了胸膛。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [649, "将臣", "「可以吗？真的可以吗？我真的要摸了哦」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [650, "ムラサメ", "「都说了随便摸」", "mur001_044.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [651, "", "明明看得这么清楚，伸出手摸却摸不到，只会从中穿过去，这究竟是怎样一种感觉？", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [652, "", "是什么感觉都没有吗……还是说，像刚才的亮光一样，能感受到淡淡的温暖？", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [653, "", "我把手伸向小雨。", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [654, "", "然后，在快要穿过小雨身体的时候，我感受到的是――", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [655, "将臣", "「……」", null, "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [656, "ムラサメ", "「……」", "mur001_045.ogg", "神社_神社内d", "bgm43.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [657, "将臣", "「……咦？」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [658, "", "好像……有什么东西挡住了？", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [659, "", "温暖的触感从我的手掌传来。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [660, "", "这份温暖绝不是幻觉。", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [661, "将臣", "「……这、这是……」", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [662, "", "这个手感是——", null, "神社_神社内d", "bgm25.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [663, "将臣", "「好硬……！？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [664, "", "没错，摸上去很硬！", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [665, "", "硬邦邦的，根本穿不过去。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [666, "ムラサメ", "「咦……咦……哎……主、主、主、主主主人」", "mur001_046.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [667, "将臣", "「这，到底是——」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [668, "ムラサメ", "「啊啊啊————————！！」", "mur001_047.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [669, "将臣", "「——哇！好疼！」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [670, "", "我被一把推开，一屁股坐到了地上。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [671, "ムラサメ", "「咦……竟然推出去这么远。真、真的碰得到……？」", "mur001_048.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [672, "将臣", "「突然推我干什么！？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [673, "ムラサメ", "「还还还还还不是因为主人摸本座的胸部！」", "mur001_049.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [674, "将臣", "「——什么！？胸部！？刚才摸到的是胸部！？我头一次摸到女孩子的胸部……」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [675, "将臣", "「手感怎么跟想象中的不太一样……好硬……」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [676, "ムラサメ", "「你、你说什么！？你你你你你是在愚弄本座吗」", "mur001_050.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [677, "将臣", "「啊，没有，刚才一不小心说了实话——」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [678, "ムラサメ", "「你这————！！」", "mur001_051.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [679, "将臣", "「哇！？对不起！是我不对！」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [680, "将臣", "「萝莉万岁！飞机场最棒了！搓衣板超赞！」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [681, "ムラサメ", "「竟然一边道歉一边损人！到外面去，本座要跟你单挑！」", "mur001_052.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [682, "ムラサメ", "「再、再说了，硬的是骨头！主人刚才摸的是本座胸前的骨头！」", "mur001_053.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [683, "", "是、是这么回事吗……？", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [684, "ムラサメ", "「被摸了……竟然被摸了……可恶…………」", "mur001_054.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [685, "将臣", "「对不起。真的很抱歉。我竟然摸了少女的胸部，我真是罪该万死」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [686, "将臣", "「不过，请听我解释，我不是故意的。是你告诉我手会穿过身体的啊？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [687, "ムラサメ", "「当、当然了！所以本座才让你摸的……」", "mur001_055.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [688, "ムラサメ", "「而且，本座能把你推出去，这也很奇怪」", "mur001_056.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [689, "", "小雨说着，又一次把手伸向了丛雨丸的刀柄，但还是从中间穿了过去。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [690, "将臣", "「因为我被丛雨丸选中了，所以才能做到？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [691, "ムラサメ", "「不，应该不可能，但是……嗯……」", "mur001_057.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [692, "ムラサメ", "「想不通。胸……胸部被摸了之后，本座都没法好好思考了」", "mur001_058.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [693, "", "说实话，我完全没感觉我有摸到胸部……", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [694, "ムラサメ", "「主人！！」", "mur001_059.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [695, "将臣", "「——咦！？怎、怎么了，我什么都没说啊」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [696, "ムラサメ", "「但你心里想了，看你脸上的表情就知道你刚才在想“我没觉得我摸到胸部了啊”」", "mur001_060.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [697, "将臣", "「……这么明显吗？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [698, "ムラサメ", "「果然如此！」", "mur001_061.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [699, "将臣", "「该死，你竟然套我话！？」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [700, "玄十郎", "「你在闹什么呢」", "gen001_025.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [701, "将臣", "「外、外公！」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [702, "玄十郎", "「……嗯？我以为你在跟谁说话呢……\\n只有你一个人吗？」", "gen001_026.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [703, "将臣", "「……」", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [704, "", "外公问我的时候，表情很认真。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [705, "ムラサメ", "「你看，本座没骗你吧？然而为什么，只有主人可以……」", "mur001_062.ogg", "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [706, "", "小雨小声嘀咕了起来，好像在思考什么事情。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [707, "", "外公和小雨肯定不会参与那种无聊的整人游戏……也就是说刚才发生在我身上的事确实很不寻常。", null, "神社_神社内d", "bgm22.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [708, "玄十郎", "「将臣？」", "gen001_027.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [709, "将臣", "「呃，这个……没什么，不用在意」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [710, "将臣", "「不过有件事得说一下，关于被我折断的那把刀……」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [711, "玄十郎", "「哦，关于这个……嗯！？刀身已经……」", "gen001_028.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [712, "", "本已折断的丛雨丸现在却复原了。看着完好如初的刀身，外公不由得睁大了眼睛。", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [713, "玄十郎", "「这是怎么复原的？」", "gen001_029.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [714, "将臣", "「这个，该怎么说明呢……」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [715, "将臣", "「是刀上的精灵，把这把刀复、复原的……我要是这么说，你会不会发火？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [716, "玄十郎", "「你是说丛雨大人吗？」", "gen001_030.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [717, "将臣", "「哎？外公你知道啊？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [718, "玄十郎", "「我也只是听说过。是能看见丛雨大人的人告诉我的」", "gen001_031.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [719, "将臣", "「……还有其他人能看到吗？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [720, "ムラサメ", "「有些人是例外，本座不是跟你说了嘛」", "mur001_063.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [721, "", "仔细一想，她确实说过。", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [722, "玄十郎", "「还有就是，关于丛雨丸的事……既然你已经成为了神刀的执刀人，就得担负起相应的责任」", "gen001_032.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [723, "将臣", "「责……任……」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [724, "", "虽说刀身已经复原，但是现在这个状态，拔刀的活动肯定是办不了了。", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [725, "", "动点手脚的话或许还能继续举办活动……", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [726, "玄十郎", "「你不能住在我那里了」", "gen001_033.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [727, "将臣", "「难不成，要、要进监狱！？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [728, "玄十郎", "「负责不是指这个」", "gen001_034.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [729, "将臣", "「那、那是要赔偿损失？去地底下强制劳动！？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [730, "玄十郎", "「冷静点。先听我说」", "gen001_035.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [731, "玄十郎", "「有个人要介绍给你认识一下」", "gen001_036.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [732, "安晴", "「你好，有地将臣。初次见面，我叫朝武安晴，是建实神社的神主」", "yas001_001.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [733, "安晴", "「不用拘谨，叫我安晴就好了。我就直接叫你将臣吧」", "yas001_002.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [734, "", "向我打招呼的，就是之前那位一身神主打扮和外公聊天的男性。", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [735, "将臣", "「啊，您好您好。这次的事给您添了那么多麻烦，真的十分抱歉」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [736, "安晴", "「不不，别客气，我才应该道歉。从今天开始，可能就要给你添不少麻烦了」", "yas001_003.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [737, "将臣", "「这个……一人做事一人当。只要在我能力范围内，我一定尽量去做」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [738, "将臣", "「那么，具体需要我做些什么呢？」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [739, "安晴", "「是这么回事，将臣」", "yas001_004.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [740, "将臣", "「嗯」", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [741, "安晴", "「芳乃，进来吧」", "yas001_005.ogg", "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [742, "", "门被推开，从门后走出来一位女性。", null, "神社_神社内d", "bgm39.opus", {"char": "芦花", "file": "", "dress": "", "face": ""}], [743, "将臣", "「哎……？是之前的……巫女小姐……？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "22"}], [744, "芳乃", "「初次见面，我叫朝武芳乃」", "yos001_001.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [745, "将臣", "「初次见面，我叫有地将臣」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [746, "芳乃", "「请问，听说你拔出了丛雨丸，这是真的吗？」", "yos001_002.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "17"}], [747, "将臣", "「啊，嗯。倒也不是把刀拔出来……是折断了」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "17"}], [748, "芳乃", "「这是真的吗？」", "yos001_003.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "11"}], [749, "将臣", "「……？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "11"}], [750, "", "她并不是在问我，而是对着别的方向问道。", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "11"}], [751, "", "在别人看来那应该是个没人的地方，但我能看到，小雨正在那里低头沉思，看上去十分伤脑筋。", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "11"}], [752, "芳乃", "「这是真的吗，丛雨大人」", "yos001_004.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "09"}], [753, "ムラサメ", "「嗯？当然是真的。你面前这个人，就是本座的主人」", "mur001_064.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [754, "将臣", "「朝武小姐也能看见小雨吗？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "01"}], [755, "芳乃", "「小……雨？」", "yos001_005.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [756, "ムラサメ", "「他是本座的主人，就破例允许他这么喊吧」", "mur001_065.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [757, "将臣", "「果然。朝武小姐看得见小雨，也能和小雨交谈吧？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [758, "ムラサメ", "「芳乃是能够和本座交谈的人类之一。不过她和主人不一样，并不是被丛雨丸选中的人」", "mur001_066.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [759, "将臣", "「因为她是巫女吗？既然她能看到，那身为神主的安晴叔叔也可以吧？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [760, "安晴", "「不，我看不见丛雨大人。我是入赘到朝武家的，只有直系血统的人才能看见」", "yas001_006.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [761, "芳乃", "「爸爸，这种事情不用说得那么详细」", "yos001_006.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "18"}], [762, "芳乃", "「丛雨大人也不用说太多」", "yos001_007.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "09"}], [763, "ムラサメ", "「可是……他既然当了本座的主人，那就……」", "mur001_067.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [764, "芳乃", "「没关系的，我会想办法解决的」", "yos001_008.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "18"}], [765, "安晴", "「唉……这可真是」", "yas001_007.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [766, "ムラサメ", "「……脾气太倔了」", "mur001_068.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [767, "将臣", "「请问，你们在说什么？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [768, "芳乃", "「这件事和有地先生没有关系，请不要在意」", "yos001_009.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [769, "", "她冷冷地说道，像是在警告我不要继续问下去。", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [770, "", "不过，她这种态度反而让我更加在意……", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [771, "安晴", "「总之先介绍一下，她是我的女儿，朝武芳乃」", "yas001_008.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [772, "安晴", "「然后，这位是将丛雨丸拔出的人，有地将臣」", "yas001_009.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [773, "芳乃", "「请多指教」", "yos001_010.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [774, "将臣", "「请多指教」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "33"}], [775, "安晴", "「那么，现在开始说正事。将臣，既然你拔出了丛雨丸，我们就不能让你一走了之了」", "yas001_010.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [776, "安晴", "「这一点，芳乃也能理解吧？」", "yas001_011.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "09"}], [777, "芳乃", "「嗯……我明白」", "yos001_011.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "30"}], [778, "安晴", "「将臣，你是愿意承担这份责任的吧？」", "yas001_012.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [779, "将臣", "「是、是的。只要我是我力所能及的事」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [780, "安晴", "「能得到你的理解真是太好了。拔出丛雨丸的责任，简单来说就是……」", "yas001_013.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [781, "安晴", "「我希望你能结婚」", "yas001_014.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [782, "将臣", "「……结婚，和谁结婚？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [783, "安晴", "「和我的女儿」", "yas001_015.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [784, "芳乃", "「……嗯？爸爸的女儿？」", "yos001_012.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [785, "安晴", "「没错」", "yas001_016.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [786, "将臣", "「结婚……吗？」", null, "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "04"}], [787, "芳乃", "「………………」", "yos001_013.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "01"}], [788, "芳乃", "「…………」", "yos001_014.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "10"}], [789, "芳乃", "「……」", "yos001_015.ogg", "神社_神社内d", "bgm39.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "05"}], [790, "芳乃", "「结婚！！！！！！！！？」", "yos001_016.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "10"}], [791, "将臣", "「结、结婚——」", null, "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [792, "将臣", "「就是那个让男性权利减半、义务翻倍的结婚吗！？」", null, "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [793, "ムラサメ", "「你的婚姻观太偏激了吧……主人」", "mur001_069.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [794, "玄十郎", "「都子家里有这么不和谐吗……？」", "gen001_037.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [795, "安晴", "「虽然我不太清楚权利和义务是怎样……大概，就是你说的那个结婚」", "yas001_017.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [796, "芳乃", "「爸、爸爸？究竟是怎么……怎、怎么会提到结婚？」", "yos001_017.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "09"}], [797, "安晴", "「我刚才说了不能让将臣就这么回去，你不也表示了理解吗」", "yas001_018.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "06"}], [798, "芳乃", "「这，这个确实理解……但也不能说结婚就结婚啊」", "yos001_018.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "06"}], [799, "安晴", "「我觉得这是必要的。尤其是对现在的你来说」", "yas001_019.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "06"}], [800, "芳乃", "「真不明白你在想什么」", "yos001_019.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "18"}], [801, "安晴", "「儿女不知父母心啊」", "yas001_020.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "18"}], [802, "芳乃", "「根本不是这么回事」", "yos001_020.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "20"}], [803, "安晴", "「总而言之，将臣，能拜托你和我女儿结婚吗」", "yas001_021.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "20"}], [804, "芳乃", "「等一下，爸爸！」", "yos001_021.ogg", "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "芳乃.stand", "dress": "舞服", "face": "06"}], [805, "将臣", "「……哎？」", null, "神社_神社内d", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}], [806, "将臣", "「哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎哎！？」", null, "空_夜空", "bgm24.opus", {"char": "芳乃", "file": "", "dress": "", "face": ""}]];
